/**
 * Handshake order required before any thread/turn method is usable:
 *
 *  1. spawn `codex app-server --listen stdio://`
 *  2. client -> `initialize` request ({ clientInfo: { name, version } })
 *  3. server -> `initialize` response (userAgent, codexHome, platform*)
 *  4. client -> `initialized` notification (no params)
 *  5. only now may the client create/read threads and start turns
 */
export const HANDSHAKE_STEPS = [
  { kind: "request", method: ClientMethods.initialize },
  { kind: "response", method: ClientMethods.initialize },
  { kind: "notification", method: ClientNotificationMethods.initialized },
] as const;
